use concord::reqwest;

fn check<T>(p: concord::Prepared<T>, query: &str, header: &[&str], case: &str) {
    let request = p.request();
    assert_eq!(request.url().query(), Some(query), "query, case {case}");
    let got: Vec<&str> = request
        .headers()
        .get_all("x-k")
        .iter()
        .map(|v| v.to_str().unwrap())
        .collect();
    assert_eq!(got, header, "header x-k, case {case}");
}

